var i=[{title:`Drei Kategorien`,text:`Anti-Extensions-Arbeit verhindert, dass sich dein unterer Rücken zu stark durchbiegt, etwa bei einem Plank oder einem Dead Bug. Anti-Rotations-Arbeit widersteht dem Verdrehen, etwa bei einem Pallof Press mit einem sicher verankerten Band. Anti-Lateralflexions-Arbeit widersteht dem seitlichen Beugen, etwa bei einem seitlichen Plank oder einem Suitcase Carry. Bauchwand, Rückenmuskeln, Zwerchfell und Hüften helfen alle, den Rumpf zu kontrollieren.`},{title:`Technikbeispiele`,text:`Richte beim Unterarm-Plank Rippen und Becken aus, drücke den Boden mit den Armen weg und atme weiter, während du stabil hältst. Bewege beim Dead Bug den gegenüberliegenden Arm und das gegenüberliegende Bein nur so weit, wie dein Rumpf kontrolliert bleibt. Halte beim seitlichen Plank eine gerade, gestützte Linie und lass die Hüfte nicht absinken.`},{title:`Steigerungen`,text:`Beginne mit kurzen Haltezeiten und kurzen Hebeln. Ein seitlicher Plank mit Kniestütze kann vor einem vollen seitlichen Plank kommen, und ein Dead Bug mit gebeugten Knien vor dem Strecken der Beine. Mache es schwerer, indem du den Hebel verlängerst, eine moderate Last ergänzt oder länger kontrolliert hältst. Wenn deine Haltung zusammenbricht, ist die Übung zu schwer geworden. Achte beim Steigern auf Atmung und Ausrichtung.`},{title:`Mehr als Planks`,text:`Crunches und andere Rumpfbeugeübungen trainieren ebenfalls die Bauchmuskeln, decken aber nicht alle Aufgaben des Cores ab. Auch Rudern, Kniebeugen und Carries lassen deinen Rumpf arbeiten, um stabil zu bleiben. Du musst nicht in einer Einheit jede Richtung trainieren. Baue über die Woche einige kontrollierte Core-Übungen ein, ausgewählt nach deiner Erfahrung und danach, wie dein unterer Rücken sie verträgt. Regelmäßig dabei zu bleiben und dich in einem Tempo zu steigern, das du verträgst, ist wichtiger.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};